from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def _json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")


def render_v2_html(trace: dict[str, Any], mapping: dict[str, Any], output_path: Path) -> Path:
    html = HTML.replace("__TRACE__", _json(trace)).replace("__MAPPING__", _json(mapping))
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(html, encoding="utf-8")
    return output_path


HTML = r'''<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AGORA V2 — Autonomous Argumentative Agents</title>
<style>
:root{--ink:#18212f;--muted:#627083;--paper:#f5f7fb;--panel:#fff;--line:#dbe2ea;--blue:#2264d1;--cyan:#00a8c7;--green:#16b978;--red:#ef4d5a;--violet:#7656a8;--amber:#e39224}
*{box-sizing:border-box}html,body{height:100%}body{margin:0;padding:12px;color:var(--ink);background:var(--paper);font:14px/1.45 Inter,Segoe UI,Arial,sans-serif;display:grid;grid-template-columns:clamp(220px,16vw,270px) minmax(600px,1fr) clamp(350px,25vw,420px);grid-template-rows:auto minmax(0,1fr);gap:12px;overflow:hidden}
.brand{grid-column:1;grid-row:1/3;position:relative;overflow:hidden;color:#fff;background:linear-gradient(155deg,#11203a,#173e78 62%,#1c67a2);border-radius:14px;padding:28px 23px;box-shadow:0 8px 28px #17304f20}.brand:after{content:'V2';position:absolute;right:18px;bottom:-22px;color:#ffffff10;font-size:130px;font-weight:950}.kicker{display:flex;align-items:center;gap:7px;color:#8fceff;font-size:11px;font-weight:850;letter-spacing:1.2px;text-transform:uppercase}.kicker:before{content:'';width:20px;height:2px;background:#4bc2e8}.brand h1{margin:16px 0 2px;font-size:46px;line-height:1;letter-spacing:2px}.subtitle{color:#f3f8ff;font-size:18px;font-weight:750;line-height:1.35}.version{display:inline-block;margin:12px 0 22px;padding:4px 8px;border:1px solid #8edcff77;border-radius:999px;color:#8edcff;font-size:10px;font-weight:900;letter-spacing:.8px}.loop{display:grid;gap:9px}.loop span{position:relative;padding:8px 10px 8px 31px;border:1px solid #ffffff18;border-radius:8px;background:#ffffff09;color:#dceaff;font-size:12px;font-weight:750}.loop span:before{content:attr(data-n);position:absolute;left:9px;color:#65d5ef;font-size:9px}.brand-note{margin-top:20px;padding:11px 12px;border-radius:10px;background:#ffffff0a;border:1px solid #ffffff17;color:#c9dcf7;font-size:12px}.brand-note b{color:#fff}
.time-panel{grid-column:2/4;grid-row:1;background:#fff;border:1px solid var(--line);border-radius:12px;padding:10px 14px;box-shadow:0 3px 16px #17304f0d}.time-row{display:grid;grid-template-columns:150px 1fr auto;align-items:center;gap:12px}.time-row+.time-row{margin-top:8px;padding-top:8px;border-top:1px solid #e6ebf1}.axis-label b{display:block;color:#173e78}.axis-label small{color:var(--muted)}.ticks{display:flex;justify-content:space-between;gap:4px}.tick{min-width:38px;padding:6px 8px;border:1px solid #cad4df;border-radius:8px;background:#fff;font-weight:800;cursor:pointer}.tick.active{color:#fff;background:var(--blue);border-color:var(--blue)}.k-ticks .tick.active{background:var(--violet);border-color:var(--violet)}.axis-value{min-width:62px;text-align:center;padding:5px 9px;border-radius:999px;color:#fff;background:var(--blue);font-weight:900}.k-value{background:var(--violet)}
.canvas{grid-column:2;grid-row:2;min-width:0;min-height:0;display:flex;flex-direction:column;overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 3px 16px #17304f0d}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 12px;border-bottom:1px solid var(--line)}.phase-strip{display:flex;align-items:center;gap:5px}.phase{padding:5px 8px;border-radius:7px;background:#edf2f8;color:#617086;font-size:10px;font-weight:900}.phase.active{color:#fff;background:var(--cyan);box-shadow:0 0 0 3px #00a8c71d}.phase-sep{color:#9aa7b7}.toolbar button,.tabs button{border:1px solid #bdc9d7;background:#fff;border-radius:8px;padding:6px 10px;cursor:pointer;font-weight:750}.graph-wrap{position:relative;flex:1;min-height:360px;background:radial-gradient(circle at 50% 45%,#fff,#f4f7fc);overflow:hidden}#graph{width:100%;height:100%}.agent{cursor:pointer}.agent rect{fill:#edf4ff;stroke:#3265a7;stroke-width:2.5;filter:drop-shadow(0 3px 4px #17304f20)}.agent.contextual rect{fill:#f1edff;stroke:#7656a8;stroke-dasharray:7 4}.agent.selected rect{stroke:var(--cyan);stroke-width:4}.agent.revised rect{filter:drop-shadow(0 0 8px #e3922488)}.agent text{text-anchor:middle;pointer-events:none;fill:#172335;font-weight:850}.agent .sub{font-size:10px;fill:#5d6c80;font-weight:650}.edge,.edge-flow{fill:none;stroke-linecap:round;stroke-linejoin:round}.edge{stroke-width:3;filter:drop-shadow(0 1px 2px #17233535)}.edge-flow{stroke:#fff;stroke-width:1.1;stroke-dasharray:6 11;pointer-events:none;animation:flow .7s linear infinite}.edge.support,.edge.provide_evidence{stroke:var(--green)}.edge.attack,.edge.challenge{stroke:var(--red)}.edge.present_argument{stroke:var(--blue)}.edge-label{font-size:9px;font-weight:900;text-anchor:middle;paint-order:stroke;stroke:#fff;stroke-width:4px;stroke-linejoin:round}.action-layer.hidden{opacity:.08}.action-layer{transition:opacity .2s}.graph-summary{position:absolute;left:12px;bottom:10px;padding:6px 9px;border:1px solid var(--line);border-radius:8px;background:#fffffff0;color:var(--muted);font-size:12px}
.rail{grid-column:3;grid-row:2;min-width:0;min-height:0;display:flex;flex-direction:column;overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 3px 16px #17304f0d}.tabs{display:flex;gap:4px;padding:9px;border-bottom:1px solid var(--line);background:#f8fafc}.tabs button{flex:1}.tabs button.active{color:#fff;background:var(--blue);border-color:var(--blue)}.panel{flex:1;min-height:0;overflow:auto;padding:14px}.panel[hidden]{display:none}.panel h2{margin:0 0 4px;font-size:19px}.panel h3{margin:15px 0 6px;font-size:11px;color:#506078;letter-spacing:.5px}.card{margin:7px 0;padding:9px 10px;border:1px solid #e0e7ef;border-radius:8px;background:#f7f9fc;font-size:12px}.card.observe{border-left:4px solid var(--cyan)}.card.reason{border-left:4px solid var(--violet)}.card.act{border-left:4px solid var(--red)}.card.revise{border-left:4px solid var(--amber)}.pill{display:inline-block;margin:2px 3px 2px 0;padding:2px 7px;border-radius:999px;background:#e9eff7;font-size:10px;font-weight:850}.metric-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.metric{padding:10px;border:1px solid #e1e8f0;border-radius:9px;background:#f8fbff}.metric b{display:block;color:#174b8a;font-size:18px}.log-line{padding:7px 8px;border-bottom:1px solid #e8edf3;font:11px/1.45 ui-monospace,SFMono-Regular,Consolas,monospace}.empty{padding:35px 10px;text-align:center;color:var(--muted)}
@keyframes flow{to{stroke-dashoffset:-34}}@media(prefers-reduced-motion:reduce){.edge-flow{animation:none}}
@media(max-width:1180px){html,body{height:auto}body{grid-template-columns:1fr;grid-template-rows:auto;overflow:auto}.brand,.time-panel,.canvas,.rail{grid-column:1;grid-row:auto}.brand{padding:20px 22px}.brand h1{font-size:38px}.loop{grid-template-columns:repeat(3,1fr)}.graph-wrap{height:620px}.rail{height:650px}.time-row{grid-template-columns:130px 1fr auto}}
</style></head><body>
<aside class="brand"><div class="kicker">Autonomous deliberation</div><h1>AGORA</h1><div class="subtitle">V2 · Argumentative Agents</div><div class="version">DETERMINISTIC BASELINE</div><div class="loop"><span data-n="01">OBSERVE</span><span data-n="02">REASON</span><span data-n="03">SELECT ACTION</span><span data-n="04">INTERACT</span><span data-n="05">REVISE BELIEF</span><span data-n="06">UPDATE STATE</span></div><div class="brand-note"><b>t</b> = thời gian sự kiện thật<br><b>k</b> = bước thảo luận nội bộ</div></aside>
<section class="time-panel"><div class="time-row"><div class="axis-label"><b>REAL TIME · t</b><small>Snapshot thông tin CTQ</small></div><div class="ticks" id="tTicks"></div><output class="axis-value" id="tValue"></output></div><div class="time-row"><div class="axis-label"><b>DELIBERATION · k</b><small>Bước agent nội bộ</small></div><div class="ticks k-ticks" id="kTicks"></div><output class="axis-value k-value" id="kValue"></output></div></section>
<main class="canvas"><div class="toolbar"><div class="phase-strip" id="phaseStrip"><span class="phase">OBSERVE</span><i class="phase-sep">→</i><span class="phase">REASON</span><i class="phase-sep">→</i><span class="phase">ACT</span><i class="phase-sep">→</i><span class="phase">REVISE</span></div><button id="replay">↻ Phát lại bước</button></div><div class="graph-wrap"><svg id="graph" viewBox="0 0 1100 680"><defs><marker id="arrowGreen" markerUnits="userSpaceOnUse" markerWidth="18" markerHeight="18" refX="15" refY="9" orient="auto"><path d="M2 4 L15 9 L2 14 L5 9 Z" fill="#16b978"/></marker><marker id="arrowRed" markerUnits="userSpaceOnUse" markerWidth="18" markerHeight="18" refX="15" refY="9" orient="auto"><path d="M2 4 L15 9 L2 14 L5 9 Z" fill="#ef4d5a"/></marker><marker id="arrowBlue" markerUnits="userSpaceOnUse" markerWidth="18" markerHeight="18" refX="15" refY="9" orient="auto"><path d="M2 4 L15 9 L2 14 L5 9 Z" fill="#2264d1"/></marker></defs><g id="edges"></g><g id="nodes"></g></svg><div class="graph-summary" id="graphSummary"></div></div></main>
<aside class="rail"><nav class="tabs"><button class="active" data-tab="reasoning">Lập luận</button><button data-tab="activity">Hoạt động</button><button data-tab="metrics">Chỉ số</button></nav><section class="panel" id="reasoning"></section><section class="panel" id="activity" hidden></section><section class="panel" id="metrics" hidden></section></aside>
<script>
const TRACE=__TRACE__,MAPPING=__MAPPING__;const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mapById=Object.fromEntries(MAPPING.viewpoints.map(v=>[v.viewpoint_id,v])),params=new URLSearchParams(location.search);let state={t:Math.max(0,Math.min(TRACE.timestamps.length-1,Number(params.get('t')||0))),k:Math.max(0,Number(params.get('k')||0)),phase:3,agent:params.get('agent'),timers:[]};
function current(){const run=TRACE.timestamps[state.t],step=run.steps[Math.min(state.k,run.steps.length-1)];return{run,step}}
function buttons(){const t=$('tTicks');t.innerHTML=TRACE.timestamps.map((r,i)=>`<button class="tick ${i===state.t?'active':''}" data-t="${i}">${esc(r.timestamp)}</button>`).join('');t.querySelectorAll('button').forEach(b=>b.onclick=()=>selectTime(+b.dataset.t));const {run}=current();state.k=Math.min(state.k,run.steps.length-1);$('kTicks').innerHTML=run.steps.map((s,i)=>`<button class="tick ${i===state.k?'active':''}" data-k="${i}">k${s.deliberation_step}</button>`).join('');$('kTicks').querySelectorAll('button').forEach(b=>b.onclick=()=>selectStep(+b.dataset.k));$('tValue').textContent=run.timestamp;$('kValue').textContent=`k${current().step.deliberation_step}`}
function selectTime(i){state.t=i;state.k=0;state.agent=null;buttons();replay()}function selectStep(i){state.k=i;state.agent=null;buttons();replay()}
function replay(){state.timers.forEach(clearTimeout);state.phase=0;render();[1,2,3].forEach((p,i)=>state.timers.push(setTimeout(()=>{state.phase=p;render()},(i+1)*320)))}
function phase(){document.querySelectorAll('.phase').forEach((el,i)=>el.classList.toggle('active',i===state.phase))}
function positions(ids){const out={},cx=550,cy=338,rx=390,ry=245;ids.forEach((id,i)=>{const a=-Math.PI/2+i*2*Math.PI/ids.length;out[id]={x:cx+Math.cos(a)*rx,y:cy+Math.sin(a)*ry}});return out}
function edgePath(a,b,index,total,reciprocal){const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,ux=dx/len,uy=dy/len,nx=-uy,ny=ux,offset=reciprocal?26+index*18:(index-(total-1)/2)*30,boundary=Math.min(82/Math.max(Math.abs(ux),.001),43/Math.max(Math.abs(uy),.001)),sx=a.x+ux*(boundary+2),sy=a.y+uy*(boundary+2),ex=b.x-ux*(boundary+3),ey=b.y-uy*(boundary+3),mx=(sx+ex)/2+nx*offset,my=(sy+ey)/2+ny*offset;return{d:`M${sx} ${sy} Q${mx} ${my} ${ex} ${ey}`,mx,my}}
function renderGraph(){const{step}=current(),agents=Object.values(step.agent_states_after).filter(a=>Object.keys(a.belief_states).length),ids=agents.map(a=>a.agent_id),pos=positions(ids),revised=new Set(step.belief_revisions.map(r=>r.agent_id));const pairCount={};step.interactions.forEach(x=>{if(x.target_agent){const key=x.actor_agent+'>'+x.target_agent;pairCount[key]=(pairCount[key]||0)+1}});const pairIndex={};let edgeHtml='';step.interactions.forEach(x=>{if(!x.target_agent||!pos[x.actor_agent]||!pos[x.target_agent])return;const key=x.actor_agent+'>'+x.target_agent,index=pairIndex[key]||0;pairIndex[key]=index+1;const reciprocal=Boolean(pairCount[x.target_agent+'>'+x.actor_agent]),p=edgePath(pos[x.actor_agent],pos[x.target_agent],index,pairCount[key],reciprocal),cls=x.action_type.toLowerCase(),marker=['SUPPORT','PROVIDE_EVIDENCE'].includes(x.action_type)?'arrowGreen':['ATTACK','CHALLENGE'].includes(x.action_type)?'arrowRed':'arrowBlue',tip=`${x.actor_agent} → ${x.target_agent}\n${x.action_type}\nArguments: ${x.source_argument_id} → ${x.target_argument_id}\nRelations: ${x.relation_ids.join(', ')||'không'}\nSources: ${x.evidence_source_ids.join(', ')||'không'}`;edgeHtml+=`<g class="action-layer ${state.phase<2?'hidden':''}"><title>${esc(tip)}</title><path class="edge ${cls}" d="${p.d}" marker-end="url(#${marker})"/><path class="edge-flow" d="${p.d}"/><text class="edge-label" x="${p.mx}" y="${p.my-7}">${esc(x.action_type)}</text></g>`});$('edges').innerHTML=edgeHtml;$('nodes').innerHTML=agents.map(a=>{const p=pos[a.agent_id],m=mapById[a.agent_id],beliefs=Object.values(a.belief_states),accepted=beliefs.filter(b=>b.agent_belief_status==='accepted').length,tip=`${a.agent_id} — ${m.name}\n${m.position_summary}\n${beliefs.length} beliefs · ${accepted} accepted`;return`<g class="agent ${m.kind==='contextual'?'contextual':''} ${state.agent===a.agent_id?'selected':''} ${state.phase===3&&revised.has(a.agent_id)?'revised':''}" data-id="${a.agent_id}" transform="translate(${p.x-82} ${p.y-43})"><title>${esc(tip)}</title><rect width="164" height="86" rx="12"/><text x="82" y="28">${esc(a.agent_id)}</text><text class="sub" x="82" y="48">${esc((m.name.length>25?m.name.slice(0,24)+'…':m.name))}</text><text class="sub" x="82" y="66">${beliefs.length} beliefs · ${accepted} accepted</text></g>`}).join('');document.querySelectorAll('.agent').forEach(n=>n.onclick=()=>{state.agent=n.dataset.id;renderPanels();renderGraph()});$('graphSummary').textContent=`${agents.length} agent · ${step.interactions.length} action đã thực thi · ${step.belief_revisions.length} belief revision`}
function reasoningPanel(){const{step,run}=current();let id=state.agent||Object.keys(step.agent_states_after).find(x=>Object.keys(step.agent_states_after[x].belief_states).length);if(!id){$('reasoning').innerHTML='<div class="empty">Không có agent active.</div>';return}state.agent=id;const o=step.observations[id],traces=step.reasoning_traces[id]||[],cands=step.candidate_actions[id]||[],chosen=step.selected_actions[id],revs=step.belief_revisions.filter(r=>r.agent_id===id),top=[...traces].sort((a,b)=>b.score_after-a.score_after).slice(0,4);$('reasoning').innerHTML=`<h2>${esc(id)} — ${esc(mapById[id].name)}</h2><div class="pill">${esc(mapById[id].kind)}</div><div class="pill">${esc(run.timestamp)} / k${step.deliberation_step}</div><h3>OBSERVATION</h3><div class="card observe"><b>${o.newly_introduced_arguments.length} argument mới · ${o.other_agent_actions.length} action nhận/thực hiện</b><br>Relations: ${o.provenance.relation_ids.map(esc).join(', ')||'không'}<br>Sources mới: ${o.newly_introduced_evidence.map(esc).join(', ')||'không'}</div><h3>REASONING</h3>${top.map(x=>`<div class="card reason"><b>${esc(x.argument_id)}</b> · ${x.score_before.toFixed(3)} → <b>${x.score_after.toFixed(3)}</b><br>canonical: ${esc(x.canonical_status)} · internal đề xuất: ${esc(x.recommended_status)}<br><small>${esc(x.reason)}</small></div>`).join('')||'<div class="card">Chưa có belief.</div>'}<h3>ACTION DECISION</h3><div class="card act"><b>${esc(chosen.action_type)}</b>${chosen.target_agent?' → '+esc(chosen.target_agent):''}<br>${esc(chosen.rationale)}<br><small>utility ${chosen.utility.toFixed(3)} · ${esc(chosen.validation_reason)}</small></div><div class="card">${cands.length} phương án: ${cands.slice(0,6).map(x=>`${esc(x.action_type)} (${x.utility.toFixed(2)})`).join(' · ')}</div><h3>BELIEF REVISION</h3>${revs.map(r=>`<div class="card revise"><b>${esc(r.argument_id)}</b>: ${r.old_confidence.toFixed(3)} → ${r.new_confidence.toFixed(3)}<br>${esc(r.old_status)} → ${esc(r.new_status)}<br><small>${esc(r.explanation)}</small></div>`).join('')||'<div class="card">Không đổi belief tại bước này.</div>'}`}
function activityPanel(){const{step,run}=current();$('activity').innerHTML=`<h2>Activity Log</h2><div class="pill">${esc(run.timestamp)} / k${step.deliberation_step}</div><div class="pill">stop: ${esc(run.stop_reason)}</div>${step.log.map(x=>`<div class="log-line">${esc(x)}</div>`).join('')}`}
function metricsPanel(){const m=current().step.society_metrics,labels={active_agents:'Active agents',active_interactions:'Interactions',support_activity:'Support activity',attack_activity:'Attack activity',belief_revisions:'Belief revisions',retractions:'Retractions',mean_internal_belief_confidence:'Mean confidence',conflict_intensity:'Conflict intensity',disagreement_indicator:'Disagreement proxy',connected_components:'Connected components'};$('metrics').innerHTML=`<h2>Society Metrics</h2><p class="card">${esc(m.modeling_note)}</p><div class="metric-grid">${Object.entries(labels).map(([k,l])=>`<div class="metric"><small>${esc(l)}</small><b>${esc(m[k])}</b></div>`).join('')}</div><h3>DOMINANT VIEWPOINT</h3><div class="card">${esc(m.dominant_viewpoint_by_defensible_active_arguments||'không có')}</div>`}
function renderPanels(){reasoningPanel();activityPanel();metricsPanel()}function render(){buttons();phase();renderGraph();renderPanels()}
document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x===b));['reasoning','activity','metrics'].forEach(id=>$(id).hidden=id!==b.dataset.tab)});$('replay').onclick=replay;render();
</script></body></html>'''
